+
+            @Override
+            public Void visit(Point point)  {
+                luceneGeometries.add(GeoShapeUtils.toLucenePoint(point));
+                return null;
+            }
+
+            @Override
+            public Void visit(Polygon polygon) {
+                luceneGeometries.add(GeoShapeUtils.toLucenePolygon(polygon));
+                return null;
+            }
+
+            @Override
